l&quot; title=&quot;Domaine de la Communaut&#233;&quot;&gt;Communaut&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Famille, Foyer, Coop&#233;ration&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Connaissance.html&quot; title=&quot;Domaine de la Connaissance&quot;&gt;Connaissance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;M&#233;moire, Pens&#233;e, A&#233;ons&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Destruction.html&quot; title=&quot;Domaine de la Destruction&quot;&gt;Destruction&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Catastrophe, Rage, Haine, Torture&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Duperie.html&quot; title=&quot;Domaine de la Duperie&quot;&gt;Duperie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Supercherie, Voleurs, Insinuation, Avarice, Embuscade&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Leau.html&quot; title=&quot;Domaine de l&amp;#39;Eau&quot;&gt;Eau&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Glace, Oc&#233;ans, Rivi&#232;res, Flux, Epaves&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Faune.html&quot; title=&quot;Domaine de la Faune&quot;&gt;Faune&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Plume, Poil&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Feu.html&quot; title=&quot;Domaine du Feu&quot;&gt;Feu&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Cendres, Fum&#233;e, Incendies&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Flore.html&quot; title=&quot;Domaine de la Flore&quot;&gt;Flore&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Croissance, Pourriture&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Folie.html&quot; title=&quot;Domaine de la Folie&quot;&gt;Folie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Cauchemars, Insanit&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Force.html&quot; title=&quot;Domaine de la Force&quot;&gt;Force&lt;/a&gt;&lt;/td&gt;&lt;td&gt;F&#233;rocit&#233;, R&#233;solution, Poing&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Gloire.html&quot; title=&quot;Domaine de la Gloire&quot;&gt;Gloire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;H&#233;ro&#239;sme, Honneur&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;td&gt;
&lt;table CLASS=&quot;tablo&quot; STYLE=&quot;width:100%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Domaine&lt;/td&gt;&lt;td&gt;Sous-domaines&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot; &gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Gu&#233;rison.html&quot; title=&quot;Domaine de la Gu&#233;rison&quot;&gt;Gu&#233;rison&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Restauration, R&#233;surrection&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Guerre.html&quot; title=&quot;Domaine de la Guerre&quot;&gt;Guerre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Sang, Tactique&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Lib&#233;ration.html&quot; title=&quot;Domaine de la Lib&#233;ration&quot;&gt;Lib&#233;ration&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Libert&#233;, R&#233;volution&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Loi.html&quot; title=&quot;Domaine de la Loi&quot;&gt;Loi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Archons, Diables, In&#233;vitables, Jugement, Kytons, Fid&#233;lit&#233;, Esclavage, Tyrannie&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Magie.html&quot; title=&quot;Domaine de la Magie&quot;&gt;Magie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Divin, Profane&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Mal.html&quot; title=&quot;Domaine du Mal&quot;&gt;Mal&lt;/a&gt;&lt;/td&gt;&lt;td&gt;D&#233;mons, Diables, Da&#233;mons, Peur, Corruption, Cannibalisme, D&#233;modandes, Kytons&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Mort.html&quot; title=&quot;Domaine de la Mort&quot;&gt;Mort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Meurtre, Mort-vivants, Psychopompes&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&